const items = $input.all();
let text = "Bugünün Gündem Başlıkları:\n";

items.slice(0, 15).forEach((item, index) => {
  text += (index + 1) + ". " + item.json.title + "\n";
});

return [{ json: { trendData: text } }];

const response = $input.first().json;
let posts = [];

const content = response.text || response.data || response.message?.content || JSON.stringify(response);
const match = content.match(/\[[\s\S]*\]/);

if (match) {
  try {
    posts = JSON.parse(match[0]);
  } catch (e) {
    posts = [{ title: 'Format Hatası', body: 'İçerik işlenemedi, manuel kontrol et.', category: 'hata', audience: 'genel' }];
  }
} else {
  posts = [{ title: 'İçerik Bulunamadı', body: content.substring(0, 200), category: 'hata', audience: 'genel' }];
}

const emoji = { isletme_ipucu: '💡', sektorel_gundem: '📌', vaka: '📊', nasil_yapilir: '📋', arac: '🛠', rakamlarla: '📈', kontrol: '✅', soru_cevap: '❓', hata: '⚠️' };

const today = new Date().toLocaleDateString('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' });

let message = 'ErgeneAI | Günlük Sektör Özeti | ' + today + '\n\n';

posts.forEach((p, i) => {
  const e = emoji[p.category] || '📝';
  message += (i + 1) + '. ' + e + ' *' + (p.title || '').replace(/[*_]/g, '') + '*\n';
  message += (p.body || '').replace(/[*_]/g, '') + '\n';
  message += '   Hedef Kitle: ' + (p.audience || 'genel').replace(/_/g, ' ').toUpperCase() + '\n\n';
});

message += '_Bu içerik ErgeneAI otonom sistemleri tarafından hazırlanmıştır._';

return [{ json: { text: message, posts: posts } }];
